//! Manifest census and entry-point generation.

use super::binding;
use super::implemented::IMPLEMENTED;
use std::fmt::Write as _;

pub(super) struct Census;

impl Census {
    pub(super) fn generate(text: &str) -> String {
        let mut output = String::new();
        output.push_str(
            "// @generated by build.rs from registry/gles2_egl.manifest — DO NOT EDIT.\n\n",
        );

        let mut gl = 0usize;
        let mut egl = 0usize;
        let mut stubs = 0usize;
        for (lineno, line) in text.lines().enumerate() {
            let line = line.trim_end();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let mut fields = line.split('\t');
            let lib = fields.next().unwrap_or("");
            let name = fields.next().unwrap_or("");
            let ret = fields.next().unwrap_or("void");
            let params = fields.next().unwrap_or("");
            if name.is_empty() {
                panic!("manifest line {}: empty name: {line:?}", lineno + 1);
            }
            match lib {
                "GL" => gl += 1,
                "EGL" => egl += 1,
                other => panic!("manifest line {}: unknown lib {other:?}", lineno + 1),
            }
            if IMPLEMENTED.contains(&name) {
                continue;
            }
            stubs += 1;
            binding::emit_stub(&mut output, lib, name, ret, params);
        }

        writeln!(output, "\n/// Total GLES2 entry points in the manifest.").unwrap();
        writeln!(output, "pub const GLES2_ENTRYPOINTS: usize = {gl};").unwrap();
        writeln!(output, "/// Total EGL entry points in the manifest.").unwrap();
        writeln!(output, "pub const EGL_ENTRYPOINTS: usize = {egl};").unwrap();
        writeln!(
            output,
            "/// Total exported entry points (the exported surface)."
        )
        .unwrap();
        writeln!(
            output,
            "pub const GLES_EGL_ENTRYPOINTS: usize = {};",
            gl + egl
        )
        .unwrap();
        writeln!(
            output,
            "/// Entry points emitted as default stubs (not yet hand-implemented)."
        )
        .unwrap();
        writeln!(output, "pub const GENERATED_STUBS: usize = {stubs};").unwrap();
        writeln!(
            output,
            "/// Entry points with real hand-written bodies in `src/driver.rs`."
        )
        .unwrap();
        writeln!(
            output,
            "pub const IMPLEMENTED_ENTRYPOINTS: usize = {};",
            IMPLEMENTED.len()
        )
        .unwrap();

        output
    }
}
